-- CAFY: make the TESTING jobs tables an exact copy of live's structure.
-- Generated by scripts/dev/buildTestingSetup.ts from the read-only live export. Run in TESTING only.
-- Nothing is deleted: existing testing tables are renamed to <name>_backup_20261102.
BEGIN;
SET LOCAL check_function_bodies = off;

-- 1. Safety: stop unless this is the testing database.
DO $cafy$ BEGIN
  IF to_regclass('public.mentors') IS NOT NULL THEN
    RAISE EXCEPTION 'STOP: this is not the testing database. Nothing was changed.';
  END IF;
END $cafy$;

-- 2. Keep the old testing tables as backups (renamed with their indexes and sequences). Skipped on a re-run.
DO $cafy$
DECLARE t text; r record;
BEGIN
  IF to_regclass('public.cafy_testing_replica') IS NOT NULL THEN
    RAISE NOTICE 'Already set up before: backups kept as they are';
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY['companies', 'part_time_companies_UK', 'part_time_jobs_UK', 'jobs', 'jobs_IR', 'directory_employers', 'job_reports'] LOOP
    IF to_regclass(format('public.%I', t)) IS NULL THEN CONTINUE; END IF;
    FOR r IN SELECT i.relname FROM pg_index x JOIN pg_class i ON i.oid = x.indexrelid WHERE x.indrelid = format('public.%I', t)::regclass LOOP
      EXECUTE format('ALTER INDEX public.%I RENAME TO %I', r.relname, left(r.relname, 50) || '_bk20261102');
    END LOOP;
    FOR r IN SELECT s.relname FROM pg_class s JOIN pg_depend d ON d.objid = s.oid
             WHERE s.relkind = 'S' AND d.refobjid = format('public.%I', t)::regclass AND d.deptype IN ('a', 'i') LOOP
      EXECUTE format('ALTER SEQUENCE public.%I RENAME TO %I', r.relname, left(r.relname, 50) || '_bk20261102');
    END LOOP;
    EXECUTE format('ALTER TABLE public.%I RENAME TO %I', t, t || '_backup_20261102');
  END LOOP;
END $cafy$;

-- 3. Extensions used by search.
CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";
CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA "public";

-- 4. Id sequences.
CREATE SEQUENCE IF NOT EXISTS public."jobs_IR_id_seq";
CREATE SEQUENCE IF NOT EXISTS public."jobs_id_seq";
CREATE SEQUENCE IF NOT EXISTS public."part_time_jobs_UK_id_seq";

-- 5. Tables, exactly as on live.

CREATE TABLE IF NOT EXISTS public."companies" (
  "id" text NOT NULL,
  "trading_name" text,
  "companies_house_name" text,
  "url" text,
  "url_linkedin" text,
  "description" text,
  "policy" text,
