  "active_jobs_count" text,
  "url_favicon" text,
  "licensed_sponsor" text,
  "estimated_num_employees_label" text,
  "ats_provider" text,
  "ats_board_token" text,
  "careers_url" text,
  "linkedin_id" text,
  "ats_status" text,
  "ats_last_validated" text,
  "ats_failure_count" text,
  "created_at" text,
  "updated_at" text,
  "cos_used_count_2025" text,
  "sponsored_employees_count" text,
