  "sync_market" text DEFAULT 'uk'::text NOT NULL,
  "part_time_catalog" boolean DEFAULT false NOT NULL,
  "sponsor_licence" text DEFAULT 'unchecked'::text,
  "sponsor_licence_source" text,
