);

CREATE TABLE IF NOT EXISTS public."part_time_companies_UK" (
  "id" text NOT NULL,
  "trading_name" text NOT NULL,
  "sector" text,
  "careers_url" text,
  "url" text,
  "evidence" text,
  "ats_provider" text,
  "ats_board_token" text,
  "ats_status" text,
  "ats_failure_count" integer DEFAULT 0 NOT NULL,
