);

CREATE TABLE IF NOT EXISTS public."part_time_jobs_UK" (
  "id" integer DEFAULT nextval('"part_time_jobs_UK_id_seq"'::regclass) NOT NULL,
  "company_id" text,
  "title" text NOT NULL,
  "url" text NOT NULL,
  "location" text,
  "city" text,
  "nation" text,
  "department" text,
  "description" text,
  "salary" text,
  "level" text,
  "sector" text,
  "job_type" text,
  "source" text DEFAULT 'backfill'::text NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "last_seen_at" timestamp with time zone DEFAULT now(),
  "part_time_company_id" text
