CREATE TABLE IF NOT EXISTS public."jobs" (
  "id" integer DEFAULT nextval('jobs_id_seq'::regclass) NOT NULL,
  "company_id" integer,
  "title" text NOT NULL,
  "url" text NOT NULL,
  "location" text,
  "department" text,
  "description" text,
  "salary" text,
  "level" text,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "last_seen_at" timestamp with time zone DEFAULT now(),
  "sector" text,
  "search_vector" tsvector,
  "all_locations" text[],
  "sector_embedding" text,
  "job_type" text,
  "level_source" text,
  "soc_code" text,
  "soc_title" text,
  "soc_evidence" text,
  "sponsorship_outcome" text,
  "sponsorship_route" text,
  "sponsorship_list_as_of" date,
  "salary_check" text,
