CREATE TABLE IF NOT EXISTS public."jobs_IR" (
  "id" integer DEFAULT nextval('"jobs_IR_id_seq"'::regclass) NOT NULL,
  "company_id" integer,
  "title" text NOT NULL,
  "url" text NOT NULL,
  "location" text,
  "department" text,
  "description" text,
  "salary" text,
  "level" text,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "last_seen_at" timestamp with time zone DEFAULT now(),
  "sector" text,
  "search_vector" tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig, ((((COALESCE(title, ''::text) || ' '::text) || COALESCE(department, ''::text)) || ' '::text) || COALESCE(sector, ''::text)))) STORED,
  "source" text DEFAULT 'ats'::text NOT NULL,
  "sector_embedding" text,
  "job_type" text,
  "level_source" text
);

CREATE TABLE IF NOT EXISTS public."directory_employers" (
  "id" bigint NOT NULL,
