DO $cafy$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'part_time_jobs_uk_nation_allowed' AND conrelid = 'public."part_time_jobs_UK"'::regclass) THEN EXECUTE 'ALTER TABLE public."part_time_jobs_UK" ADD CONSTRAINT "part_time_jobs_uk_nation_allowed" CHECK (((nation IS NULL) OR (nation = ANY (ARRAY[''England''::text, ''Scotland''::text, ''Wales''::text, ''Northern Ireland''::text]))))'; END IF; END $cafy$;
DO $cafy$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'part_time_jobs_uk_source_allowed' AND conrelid = 'public."part_time_jobs_UK"'::regclass) THEN EXECUTE 'ALTER TABLE public."part_time_jobs_UK" ADD CONSTRAINT "part_time_jobs_uk_source_allowed" CHECK ((source = ANY (ARRAY[''backfill''::text, ''daily''::text, ''catalog''::text])))'; END IF; END $cafy$;
DO $cafy$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'part_time_companies_UK_linked_company_id_fkey' AND conrelid = 'public."part_time_companies_UK"'::regclass) THEN EXECUTE 'ALTER TABLE public."part_time_companies_UK" ADD CONSTRAINT "part_time_companies_UK_linked_company_id_fkey" FOREIGN KEY (linked_company_id) REFERENCES companies(id) ON DELETE SET NULL'; END IF; END $cafy$;
