-- 8. Search functions.
CREATE OR REPLACE FUNCTION public.jobs_matches_search(j jobs, p_query text, p_company_ids integer[])
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    q text := trim(lower(coalesce(p_query, '')));
    tsq tsquery;
BEGIN
    IF q = '' OR length(q) > 100 THEN
        RETURN false;
    END IF;

    tsq := plainto_tsquery('english', q);

    RETURN (
        j.search_vector @@ tsq
        OR coalesce(j.title, '') ILIKE '%' || q || '%'
        OR coalesce(j.department, '') ILIKE '%' || q || '%'
        OR coalesce(j.location, '') ILIKE '%' || q || '%'
        OR coalesce(j.sector, '') ILIKE '%' || q || '%'
        OR (p_company_ids IS NOT NULL AND j.company_id = ANY (p_company_ids))
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.jobs_passes_search_filters(j jobs, p_excluded_ids text[], p_excluded_company_ids integer[], p_company_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_excluded_ids IS NOT NULL AND j.id::text = ANY (p_excluded_ids) THEN
        RETURN false;
    END IF;
    IF p_excluded_company_ids IS NOT NULL AND j.company_id = ANY (p_excluded_company_ids) THEN
        RETURN false;
    END IF;
    IF p_company_id IS NOT NULL AND j.company_id IS DISTINCT FROM p_company_id THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$function$;
CREATE OR REPLACE FUNCTION public.jobs_portal_list_job_ids(p_mode text, p_shuffle_seed text, p_sectors text[] DEFAULT NULL::text[], p_job_levels text[] DEFAULT NULL::text[], p_excluded_job_ids text[] DEFAULT NULL::text[], p_excluded_company_ids bigint[] DEFAULT NULL::bigint[], p_company_id bigint DEFAULT NULL::bigint, p_q_term text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)
 RETURNS TABLE(id text)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_has_sectors boolean := p_sectors IS NOT NULL AND cardinality(p_sectors) > 0;
    v_has_levels boolean := p_job_levels IS NOT NULL AND cardinality(p_job_levels) > 0;
BEGIN
    RETURN QUERY
    SELECT j.id::text
    FROM jobs j
    INNER JOIN companies c ON c.id = j.company_id
    WHERE
        CASE
            WHEN p_q_term IS NOT NULL AND length(trim(p_q_term)) > 0 THEN
                (
                    j.title ILIKE '%' || p_q_term || '%'
                    OR j.department ILIKE '%' || p_q_term || '%'
                    OR j.location ILIKE '%' || p_q_term || '%'
                )
            WHEN p_mode = 'preferred' THEN
                CASE
                    WHEN v_has_sectors AND v_has_levels THEN
                        j.sector = ANY (p_sectors) AND j.level = ANY (p_job_levels)
                    WHEN v_has_sectors THEN
                        j.sector = ANY (p_sectors)
                    WHEN v_has_levels THEN
                        j.level = ANY (p_job_levels)
                    ELSE
                        TRUE
                END
            WHEN p_mode = 'secondary' THEN
                v_has_sectors
                AND v_has_levels
                AND j.sector = ANY (p_sectors)
                AND (j.level IS NULL OR NOT (j.level = ANY (p_job_levels)))
            WHEN p_mode = 'remainder_merged' THEN
                v_has_sectors
                AND (j.sector IS NULL OR NOT (j.sector = ANY (p_sectors)))
            WHEN p_mode = 'remainder' THEN
                CASE
                    WHEN v_has_sectors THEN
                        j.sector IS NOT NULL AND NOT (j.sector = ANY (p_sectors))
                    WHEN v_has_levels THEN
                        j.level IS NULL OR NOT (j.level = ANY (p_job_levels))
                    ELSE
                        TRUE
                END
            WHEN p_mode = 'all' THEN
                TRUE
            ELSE
                FALSE
        END
        AND (p_excluded_job_ids IS NULL OR NOT (j.id::text = ANY (p_excluded_job_ids)))
        AND (
            p_excluded_company_ids IS NULL
            OR NOT (j.company_id = ANY (p_excluded_company_ids))
        )
        AND (p_company_id IS NULL OR j.company_id = p_company_id)
    ORDER BY jobs_shuffle_key(j.id::text, p_shuffle_seed)
    OFFSET GREATEST(p_offset, 0)
    LIMIT GREATEST(p_limit, 0);
END;
$function$;
CREATE OR REPLACE FUNCTION public.jobs_search_rank(j jobs, p_query text)
 RETURNS real
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    q text := trim(lower(coalesce(p_query, '')));
    tsq tsquery;
    fts_rank real;
    trgm_boost real;
BEGIN
    IF q = '' OR length(q) > 100 THEN
        RETURN 0;
    END IF;

    tsq := plainto_tsquery('english', q);
    fts_rank := ts_rank_cd(j.search_vector, tsq, 32)::real;

    trgm_boost := greatest(
        similarity(coalesce(j.title, ''), q),
        similarity(coalesce(j.department, ''), q),
        similarity(coalesce(j.location, ''), q),
        similarity(coalesce(j.sector, ''), q)
    )::real * 0.3;

    RETURN fts_rank + trgm_boost;
END;
$function$;
CREATE OR REPLACE FUNCTION public.jobs_search_vector_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.search_vector :=
        setweight(to_tsvector('english', coalesce(NEW.title, '')), 'A') ||
        setweight(to_tsvector('english', coalesce(NEW.department, '')), 'B') ||
        setweight(to_tsvector('english', coalesce(NEW.location, '')), 'C') ||
        setweight(to_tsvector('english', coalesce(NEW.sector, '')), 'C');
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.jobs_shuffle_key(p_id text, p_seed text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
    SELECT encode(digest(convert_to(p_seed || ':' || p_id, 'UTF8'), 'sha256'), 'hex');
$function$;
CREATE OR REPLACE FUNCTION public.list_portal_directory_companies(p_catalog text DEFAULT 'uk'::text, p_search text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20)
 RETURNS TABLE(company_id bigint, job_count bigint, register_volume integer)
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT nullif(btrim(coalesce(p_search, '')), '') AS search_raw
  ),
  live AS (
    SELECT j.company_id::text AS company_id, COUNT(*)::bigint AS job_count
    FROM public.jobs j
    WHERE lower(coalesce(p_catalog, 'uk')) <> 'ireland'
      AND j.company_id IS NOT NULL
    GROUP BY j.company_id::text
    UNION ALL
    SELECT j.company_id::text AS company_id, COUNT(*)::bigint AS job_count
    FROM public."jobs_IR" j
    WHERE lower(coalesce(p_catalog, 'uk')) = 'ireland'
      AND j.company_id IS NOT NULL
    GROUP BY j.company_id::text
  )
  SELECT
    d.id AS company_id,
    COALESCE(l.job_count, d.job_count, 0)::bigint AS job_count,
    d.register_volume
  FROM public.directory_employers d
  LEFT JOIN live l ON l.company_id = COALESCE(d.company_id, d.id::text)
  CROSS JOIN q
  WHERE d.catalog = lower(coalesce(p_catalog, 'uk'))
    AND (
      q.search_raw IS NULL
      OR d.display_name ILIKE '%' || q.search_raw || '%'
      OR coalesce(d.legal_name, '') ILIKE '%' || q.search_raw || '%'
    )
  ORDER BY
    COALESCE(l.job_count, d.job_count, 0) DESC,
    d.register_volume DESC,
    d.display_name ASC NULLS LAST,
    d.id ASC
  OFFSET GREATEST(coalesce(p_offset, 0), 0)
  LIMIT LEAST(GREATEST(coalesce(p_limit, 20), 1), 50);
$function$;
CREATE OR REPLACE FUNCTION public.list_portal_directory_companies_count(p_catalog text DEFAULT 'uk'::text, p_search text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT nullif(btrim(coalesce(p_search, '')), '') AS search_raw
  )
  SELECT COUNT(*)::bigint
  FROM public.directory_employers d
  CROSS JOIN q
  WHERE d.catalog = lower(coalesce(p_catalog, 'uk'))
    AND (
      q.search_raw IS NULL
      OR d.display_name ILIKE '%' || q.search_raw || '%'
      OR coalesce(d.legal_name, '') ILIKE '%' || q.search_raw || '%'
    );
$function$;
CREATE OR REPLACE FUNCTION public.match_jobs_fuzzy(search_role text, match_limit integer DEFAULT 5, min_similarity real DEFAULT 0.15)
 RETURNS SETOF jobs
 LANGUAGE sql
 STABLE
AS $function$
  select *
  from jobs
  where similarity(title, search_role) > min_similarity
     or title ilike '%' || search_role || '%'
  order by similarity(title, search_role) desc, last_seen_at desc nulls last
  limit match_limit;
$function$;
CREATE OR REPLACE FUNCTION public.search_jobs_count(p_role_query text DEFAULT NULL::text, p_where_query text DEFAULT NULL::text, p_company_ids integer[] DEFAULT NULL::integer[], p_excluded_ids text[] DEFAULT NULL::text[], p_excluded_company_ids integer[] DEFAULT NULL::integer[], p_company_id integer DEFAULT NULL::integer, p_sectors text[] DEFAULT NULL::text[], p_levels text[] DEFAULT NULL::text[], p_job_types text[] DEFAULT NULL::text[])
 RETURNS bigint
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT
      nullif(btrim(coalesce(p_role_query, '')), '') AS role_raw,
      nullif(btrim(coalesce(p_where_query, '')), '') AS where_raw
  )
  SELECT count(*)::bigint
  FROM public.jobs j
  CROSS JOIN q
  WHERE (q.role_raw IS NOT NULL OR q.where_raw IS NOT NULL)
    AND (
      q.role_raw IS NULL
      OR j.title ILIKE '%' || q.role_raw || '%'
      OR coalesce(j.department, '') ILIKE '%' || q.role_raw || '%'
    )
    AND (
      q.where_raw IS NULL
      OR coalesce(j.location, '') ILIKE '%' || q.where_raw || '%'
      OR (p_company_ids IS NOT NULL AND j.company_id = ANY (p_company_ids))
    )
    AND (p_excluded_ids IS NULL OR NOT (j.id::text = ANY (p_excluded_ids)))
    AND (p_excluded_company_ids IS NULL OR NOT (j.company_id = ANY (p_excluded_company_ids)))
    AND (p_company_id IS NULL OR j.company_id = p_company_id);
$function$;
CREATE OR REPLACE FUNCTION public.search_jobs_ir_count(p_role_query text DEFAULT NULL::text, p_where_query text DEFAULT NULL::text, p_company_ids integer[] DEFAULT NULL::integer[], p_excluded_ids text[] DEFAULT NULL::text[], p_excluded_company_ids integer[] DEFAULT NULL::integer[], p_company_id integer DEFAULT NULL::integer, p_sectors text[] DEFAULT NULL::text[], p_levels text[] DEFAULT NULL::text[], p_job_types text[] DEFAULT NULL::text[])
 RETURNS bigint
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT
      nullif(btrim(coalesce(p_role_query, '')), '') AS role_raw,
      nullif(btrim(coalesce(p_where_query, '')), '') AS where_raw
  )
  SELECT count(*)::bigint
  FROM public."jobs_IR" j
  CROSS JOIN q
  WHERE (q.role_raw IS NOT NULL OR q.where_raw IS NOT NULL)
    AND (
      q.role_raw IS NULL
      OR j.title ILIKE '%' || q.role_raw || '%'
      OR coalesce(j.department, '') ILIKE '%' || q.role_raw || '%'
    )
    AND (
      q.where_raw IS NULL
      OR coalesce(j.location, '') ILIKE '%' || q.where_raw || '%'
      OR (p_company_ids IS NOT NULL AND j.company_id = ANY (p_company_ids))
    )
    AND (p_excluded_ids IS NULL OR NOT (j.id::text = ANY (p_excluded_ids)))
    AND (p_excluded_company_ids IS NULL OR NOT (j.company_id = ANY (p_excluded_company_ids)))
    AND (p_company_id IS NULL OR j.company_id = p_company_id);
$function$;
CREATE OR REPLACE FUNCTION public.search_jobs_ir_page(p_role_query text DEFAULT NULL::text, p_where_query text DEFAULT NULL::text, p_company_ids integer[] DEFAULT NULL::integer[], p_excluded_ids text[] DEFAULT NULL::text[], p_excluded_company_ids integer[] DEFAULT NULL::integer[], p_company_id integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20, p_sectors text[] DEFAULT NULL::text[], p_levels text[] DEFAULT NULL::text[], p_job_types text[] DEFAULT NULL::text[])
 RETURNS TABLE(job_id bigint)
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT
      nullif(btrim(coalesce(p_role_query, '')), '') AS role_raw,
      nullif(btrim(coalesce(p_where_query, '')), '') AS where_raw
  )
  SELECT j.id::bigint AS job_id
  FROM public."jobs_IR" j
  CROSS JOIN q
  WHERE (q.role_raw IS NOT NULL OR q.where_raw IS NOT NULL)
    AND (
      q.role_raw IS NULL
      OR j.title ILIKE '%' || q.role_raw || '%'
      OR coalesce(j.department, '') ILIKE '%' || q.role_raw || '%'
    )
    AND (
      q.where_raw IS NULL
      OR coalesce(j.location, '') ILIKE '%' || q.where_raw || '%'
      OR (p_company_ids IS NOT NULL AND j.company_id = ANY (p_company_ids))
    )
    AND (p_excluded_ids IS NULL OR NOT (j.id::text = ANY (p_excluded_ids)))
    AND (p_excluded_company_ids IS NULL OR NOT (j.company_id = ANY (p_excluded_company_ids)))
    AND (p_company_id IS NULL OR j.company_id = p_company_id)
  ORDER BY
    CASE
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.sector = ANY (p_sectors)
       AND j.level = ANY (p_levels)
       AND j.job_type = ANY (p_job_types) THEN 0
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.sector = ANY (p_sectors)
       AND j.job_type = ANY (p_job_types) THEN 1
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND j.sector = ANY (p_sectors)
       AND j.level = ANY (p_levels) THEN 2
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND j.sector = ANY (p_sectors) THEN 3
      WHEN p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.level = ANY (p_levels)
       AND j.job_type = ANY (p_job_types) THEN 4
      WHEN p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND j.level = ANY (p_levels) THEN 5
      WHEN p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.job_type = ANY (p_job_types) THEN 6
      ELSE 7
    END,
    j.created_at DESC,
    j.id DESC
  OFFSET GREATEST(coalesce(p_offset, 0), 0)
  LIMIT GREATEST(LEAST(coalesce(p_limit, 20), 50), 1);
$function$;
CREATE OR REPLACE FUNCTION public.search_jobs_page(p_role_query text DEFAULT NULL::text, p_where_query text DEFAULT NULL::text, p_company_ids integer[] DEFAULT NULL::integer[], p_excluded_ids text[] DEFAULT NULL::text[], p_excluded_company_ids integer[] DEFAULT NULL::integer[], p_company_id integer DEFAULT NULL::integer, p_offset integer DEFAULT 0, p_limit integer DEFAULT 20, p_sectors text[] DEFAULT NULL::text[], p_levels text[] DEFAULT NULL::text[], p_job_types text[] DEFAULT NULL::text[])
 RETURNS TABLE(job_id bigint)
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (
    SELECT
      nullif(btrim(coalesce(p_role_query, '')), '') AS role_raw,
      nullif(btrim(coalesce(p_where_query, '')), '') AS where_raw
  )
  SELECT j.id::bigint AS job_id
  FROM public.jobs j
  CROSS JOIN q
  WHERE (q.role_raw IS NOT NULL OR q.where_raw IS NOT NULL)
    AND (
      q.role_raw IS NULL
      OR j.title ILIKE '%' || q.role_raw || '%'
      OR coalesce(j.department, '') ILIKE '%' || q.role_raw || '%'
    )
    AND (
      q.where_raw IS NULL
      OR coalesce(j.location, '') ILIKE '%' || q.where_raw || '%'
      OR (p_company_ids IS NOT NULL AND j.company_id = ANY (p_company_ids))
    )
    AND (p_excluded_ids IS NULL OR NOT (j.id::text = ANY (p_excluded_ids)))
    AND (p_excluded_company_ids IS NULL OR NOT (j.company_id = ANY (p_excluded_company_ids)))
    AND (p_company_id IS NULL OR j.company_id = p_company_id)
  ORDER BY
    CASE
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.sector = ANY (p_sectors)
       AND j.level = ANY (p_levels)
       AND j.job_type = ANY (p_job_types) THEN 0
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.sector = ANY (p_sectors)
       AND j.job_type = ANY (p_job_types) THEN 1
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND j.sector = ANY (p_sectors)
       AND j.level = ANY (p_levels) THEN 2
      WHEN p_sectors IS NOT NULL AND cardinality(p_sectors) > 0
       AND j.sector = ANY (p_sectors) THEN 3
      WHEN p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.level = ANY (p_levels)
       AND j.job_type = ANY (p_job_types) THEN 4
      WHEN p_levels IS NOT NULL AND cardinality(p_levels) > 0
       AND j.level = ANY (p_levels) THEN 5
      WHEN p_job_types IS NOT NULL AND cardinality(p_job_types) > 0
       AND j.job_type = ANY (p_job_types) THEN 6
      ELSE 7
    END,
    j.created_at DESC,
    j.id DESC
  OFFSET GREATEST(coalesce(p_offset, 0), 0)
  LIMIT GREATEST(LEAST(coalesce(p_limit, 20), 50), 1);
$function$;
CREATE OR REPLACE FUNCTION public.search_jobs_ranked(p_query text, p_company_ids integer[] DEFAULT NULL::integer[], p_excluded_ids text[] DEFAULT NULL::text[], p_max_results integer DEFAULT 1000)
 RETURNS TABLE(job_id bigint, rank real)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT *
    FROM search_jobs_page(
        p_query,
        p_company_ids,
        p_excluded_ids,
        NULL,
        NULL,
        0,
        LEAST(GREATEST(coalesce(p_max_results, 1000), 1), 10000)
    );
$function$;

-- 9. Search trigger.
CREATE OR REPLACE TRIGGER jobs_search_vector_trigger BEFORE INSERT OR UPDATE OF title, department, location, sector ON public.jobs FOR EACH ROW EXECUTE FUNCTION jobs_search_vector_update();

-- 10. Row level security, as on live.
ALTER TABLE public."companies" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."directory_employers" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."job_reports" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."jobs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."jobs_IR" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."part_time_companies_UK" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."part_time_jobs_UK" ENABLE ROW LEVEL SECURITY;

-- 11. Marker: tells a re-run and the copy script that this setup was applied.
CREATE TABLE IF NOT EXISTS public.cafy_testing_replica (built_at timestamptz NOT NULL DEFAULT now(), note text);
ALTER TABLE public.cafy_testing_replica ENABLE ROW LEVEL SECURITY;
INSERT INTO public.cafy_testing_replica (note) VALUES ('jobs side copied from live structure export');
COMMIT;
